// Get the original people from Code in JavaScript
const people = $('Code in JavaScript').first().json.people;

// Classify skills deterministically
function categorize(skills) {
  const s = skills.map(x => String(x).toLowerCase());

  const automation = [
    'n8n',
    'zapier',
    'selenium',
    'web scraping',
    'langchain',
    'workflow automation'
  ];

  const data = [
    'sql',
    'mysql',
    'mongodb',
    'pandas',
    'numpy',
    'data analysis',
    'machine learning'
  ];

  const web = [
    'react',
    'javascript',
    'html',
    'css',
    'fastapi',
    'rest api',
    'rest apis',
    'docker'
  ];

  // Automation gets priority
  if (s.some(skill => automation.some(x => skill.includes(x)))) {
    return 'automation-heavy';
  }

  if (s.some(skill => data.some(x => skill.includes(x)))) {
    return 'data';
  }

  if (s.some(skill => web.some(x => skill.includes(x)))) {
    return 'web dev';
  }

  return 'web dev';
}

// Return all people with their category
return people.map(person => ({
  json: {
    ...person,
    skill_category: categorize(person.skills || [])
  }
}));
